when.condition:
@{
      var jwt = (Jwt)context.Variables["caller-jwt"];
      var roles = jwt.Claims.ContainsKey("roles") ? jwt.Claims["roles"] : new string[0];
      var project = context.Variables.GetValueOrDefault<string>("project", "");
      var tool = context.Variables.GetValueOrDefault<string>("tool", "");
      var allowed = new[] { "tool." + project + "." + tool, "tool." + project + ".all" };
      return project == "" || tool == "" || ((string)context.Variables["caller-oid"]).Length == 0 || !roles.Any(r => allowed.Contains(r, StringComparer.OrdinalIgnoreCase));
    }

return-response.set-body:
@{
          var project = context.Variables.GetValueOrDefault<string>("project", "");
          var tool = context.Variables.GetValueOrDefault<string>("tool", "");
          return new JObject(
            new JProperty("error", new JObject(
              new JProperty("code", "CALLER_NOT_ALLOWED"),
              new JProperty("message", "This agent's identity holds no role for this tool. Ask its owner for role tool." + project + "." + tool + " on the AI gateway's agent app."),
              new JProperty("correlationId", context.RequestId.ToString())))).ToString();
        }
